  "items": [
    {
      "title": "Eurostat – Government Revenue, Expenditure and Main Aggregates",
      "url_or_doi": "https://doi.org/10.2908/gov_10a_main",
      "justification": "One of the most comprehensive datasets for analyzing German fiscal policy during the 2010s and 2020s. Contains annual data on total government revenue, public expenditure, taxes, social contributions, subsidies, investment, and fiscal balances. Covers 1975–2025, allowing comparisons before and after major economic events such as the COVID-19 pandemic. Particularly useful for studying changes in Germany's fiscal policy and government spending relative to GDP."
    },
    {
      "title": "Eurostat – General Government Expenditure by Function (COFOG)",
      "url_or_doi": "https://doi.org/10.2908/gov_10a_exp",
      "justification": "Provides detailed annual government expenditure data classified by policy function, including education, healthcare, social protection, defense, infrastructure, environmental protection, and economic affairs. Covers 1990–2025. Particularly valuable for examining how Germany's public spending priorities changed between the 2010s and 2020s, including spending responses to the pandemic and shifts in defense and social expenditure."
    },
    {
      "title": "Eurostat – Government Deficit/Surplus, Debt and Associated Data",
      "url_or_doi": "https://doi.org/10.2908/gov_10dd_edpt1",
      "justification": "Contains annual government deficit, surplus, and debt indicators for Germany and other European countries. Useful for examining fiscal sustainability, budgetary balances, and public borrowing during the 2010s and 2020s. Particularly relevant for studying Germany's debt-brake policy, fiscal consolidation, pandemic-related borrowing, and changes in government indebtedness."
    },
    {
      "title": "Eurostat – General Government Debt",
      "url_or_doi": "https://doi.org/10.2908/gov_10dd_ggd",
      "justification": "Provides comparable public debt statistics for Germany and other European economies. Useful for investigating the relationship between fiscal policy, public expenditure, government borrowing, and debt accumulation. Supports analysis of Germany's fiscal position before, during, and after the COVID-19 pandemic."
    },
    {
      "title": "German Federal Statistical Office (Destatis) – Government Revenue, Expenditure and Fiscal Balance",
      "url_or_doi": "https://genesis.destatis.de/datenbank/online/statistic/81000/table/81000-0031/search/s/ODEwMDA%3D",
      "justification": "Official German national accounts dataset providing annual government revenue, expenditure, and financing balances from 1991 to 2025. Includes tax revenues, social contributions, government employee compensation, social benefits, intermediate consumption, and gross investment. Particularly suitable for detailed historical analysis of German public finances between 2010 and 2025, using statistics produced by Germany's national statistical authority."
    },
    {
      "title": "German Federal Statistical Office (Destatis) – Tax Revenue by Type of Tax",
      "url_or_doi": "https://genesis.destatis.de/datenbank/online/url/ccfa4350",
      "justification": "Official dataset containing annual German tax revenues from 1999 to 2025, disaggregated by tax category. Enables investigation of changes in income taxation, corporate taxation, consumption taxes, and other government revenue sources. Particularly relevant for studying the development of Germany's tax structure, revenue collection, and fiscal policy during the 2010s and 2020s."
    },
    {
      "title": "German Federal Statistical Office (Destatis) – Public Finance Time Series",
      "url_or_doi": "https://www.destatis.de/EN/Themes/Government/Public-Finance/Expenditure-Revenue-And-Financial-Balance-Of-Public-Budgets/Tables/expenditure-revenue-balance.html",
      "justification": "Official German public finance time series covering government budget revenues, expenditures, and financing balances. Particularly useful for analyzing the development of Germany's public budgets over time. Complements national accounts data by providing a budgetary perspective on public finances and fiscal developments."
    },
    {
      "title": "International Monetary Fund (IMF) – Government Finance Statistics (Quarterly GFS)",
      "url_or_doi": "https://data.imf.org/Datasets/QGFS",
      "justification": "Internationally standardized government finance statistics covering revenue, expenditure, fiscal deficits, government assets, and liabilities. The quarterly frequency makes this dataset particularly valuable for examining short-term fiscal developments in Germany during the 2010s and 2020s. Useful for evaluating fiscal responses to economic shocks and comparing Germany's public finances with those of other countries. Germany-specific series and their availability should be checked within the database."
    },
    {
      "title": "International Monetary Fund (IMF) – World Economic Outlook Database",
      "url_or_doi": "https://data.imf.org/datasets/WEO",
      "justification": "Comprehensive international macroeconomic dataset containing historical statistics and forecasts for government revenue, expenditure, fiscal balances, government debt, GDP, inflation, and economic growth. The October 2026 release includes annual historical data and medium-term projections. Particularly useful for studying relationships between Germany's fiscal policies and macroeconomic performance during the 2010s and 2020s, as well as expected future fiscal developments."
    },
    {
      "title": "International Monetary Fund (IMF) – World Revenue Longitudinal Database (WoRLD)",
      "url_or_doi": "https://data.imf.org/en/Datasets/WORLD",
      "justification": "Specialized government revenue dataset tracking public revenue developments across countries since the early 1990s. Useful for examining Germany's tax revenue structure, government revenue composition, and long-term trends in fiscal capacity. Particularly relevant for research on tax policy, revenue mobilization, and changes in the relationship between taxation and economic activity."
    },
    {
      "title": "OECD Data Explorer – Annual Government Expenditure by Function",
      "url_or_doi": "https://data-explorer.oecd.org/vis?df%5Bag%5D=OECD.SDD.NAD&df%5Bds%5D=DisseminateFinalDMZ&df%5Bid%5D=DSD_NASEC10%40DF_TABLE11&dq=A.ITA.S13...OTE.....V..&lo=5&lom=LASTNPERIODS&to%5BTIME_PERIOD%5D=false",
      "justification": "OECD dataset providing annual public expenditure by government function, including healthcare, education, defense, environmental protection, social welfare, and economic affairs. Supports comparisons between Germany and other OECD economies. Particularly useful for examining how German government spending priorities evolved during the 2010s and 2020s. The linked OECD Data Explorer view initially filters another country; Germany can be selected using the country filter."
    },
    {
      "title": "OECD Data Explorer – National Accounts at a Glance: Government",
      "url_or_doi": "https://data-explorer.oecd.org/vis?bp=true&df%5Bag%5D=OECD.SDD.NAD&df%5Bds%5D=dsDisseminateFinalDMZ&df%5Bid%5D=DSD_NAAG_VI%40DF_NAAG_EXP&df%5Bvs%5D=&dq=A.AUS%2BAUT%2BBEL%2BCAN%2BCHL%2BCOL%2BCRI%2BCZE%2BDNK%2BEST%2BFIN%2BFRA%2BDEU%2BGRC%2BHUN%2BISL%2BIRL%2BISR%2BITA%2BJPN%2BKOR%2BLVA%2BLTU%2BLUX%2BMEX%2BNLD%2BNZL%2BNOR%2BPOL%2BPRT%2BSVK%2BSVN%2BESP%2BSWE%2BCHE%2BTUR%2BGBR%2BUSA.OTES13...&lc=en&ly%5Bcl%5D=TIME_PERIOD&ly%5Brw%5D=REF_AREA&pd=2000%2C&pg=0&snb=12&tm=NAAG&to%5BTIME_PERIOD%5D=false",
      "justification": "OECD national accounts dataset containing internationally comparable indicators of government revenue, expenditure, and public debt. Includes Germany and other OECD member countries. Particularly suitable for assessing how Germany's fiscal policies and public spending changed relative to other advanced economies during the 2010s and 2020s."
    },
    {
      "title": "OECD – Revenue Statistics 2025: Country Tables, 1990–2023",
      "url_or_doi": "https://www.oecd.org/en/publications/revenue-statistics-2025_3a264267-en/full-report/country-tables-1990-2023_39cd5d18.html",
      "justification": "Provides internationally comparable tax revenue statistics, including German revenues by major tax category and level of government. Covers 1990–2023, including the entire 2010s and the early 2020s. Particularly useful for investigating changes in Germany's tax-to-GDP ratio, income and corporate taxation, consumption taxes, and the distribution of tax revenues across federal, state, and local government."
    }
  ]
}
